mapper.select:
SELECT s.*, m.code AS material_code, m.name AS material_name, m.spec, m.unit, b.version AS bom_version FROM fin_std_cost s JOIN wms_material m ON m.id = s.material_id LEFT JOIN mes_bom b ON b.id = s.bom_id WHERE s.version_id = #{versionId} AND s.make = #{make}
AND (m.code LIKE CONCAT('%', #{keyword}, '%') OR m.name LIKE CONCAT('%', #{keyword}, '%'))
ORDER BY s.make DESC, m.code
